internal object DuaNlDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rooster_donkey" to DuaText("Een haan of ezel horen", "O Allah, ik vraag U om Uw milddadigheid (haan). — Ik zoek toevlucht bij Allah tegen Shaytan, de vervloekte (ezel).", "Bij het horen van een haan die om de gunst van Allah vraagt; bij het horen van een ezel balken zoek je toevlucht bij Shaytan.", "De haan ziet een engel en de ezel ziet een duivel."),
        "dua_something_liked" to DuaText("Iets bewonderenswaardigs zien (tegen het boze oog)", "Wat Allah heeft gewild. O Allah, zegen het.", "Als u iets bewonderenswaardigs ziet dat aan iemand toebehoort, bid dan om zegen.", "Bidden om zegen voorkomt het boze oog."),
        "dua_sell_buy_debt_repaid" to DuaText("Bij het afbetalen van een schuld", "Moge Allah u zegenen in uw familie en uw rijkdom.", "Voor de kredietverstrekker bij het afbetalen van een schuld.", "Het rendement voor een lening is dank en terugbetaling."),
        "dua_talbiyah" to DuaText("Talbiyah", "Hier ben ik, O Allah, hier ben ik. Hier ben ik. Je hebt geen partner, hier ben ik. Zeker, alle lof, zegeningen en heerschappij zijn van U. Je hebt geen partner.", "Hardop na het binnengaan van ihram.", "Het embleem van de hadj en umrah."),
        "dua_yamani_hajar" to DuaText("Tussen Rukn Yamani en Hajar Aswad", "Onze Heer, geef ons het goede in deze wereld en het goede in het Hiernamaals, en bescherm ons tegen de bestraffing van het Vuur.", "In tawaf, tussen de Jemenitische Hoek en de Zwarte Steen.", "De Profeet ﷺ reciteerde dit op deze plaats in tawaf."),
        "dua_safa_marwa" to DuaText("Over Safa en Marwah", "Niemand heeft het recht om aanbeden te worden behalve Allah, alleen, zonder partner. Aan Hem is de heerschappij en aan Hem is de lof, en Hij heeft macht over alle dingen. Niemand heeft het recht om aanbeden te worden behalve Allah alleen; Hij vervulde Zijn belofte, hielp Zijn dienaar en versloeg alleen de bondgenoten.", "Safa beklimmen en naar de Qiblah kijken (drie keer).", "De dhikr van de Profeet ﷺ over Safa en Marwah."),
        "dua_arafah" to DuaText("Beste Dua van de Dag van Arafah", "Niemand heeft het recht om aanbeden te worden behalve Allah, alleen, zonder partner. Aan Hem is de heerschappij en aan Hem is de lof, en Hij heeft macht over alle dingen.", "De Dag van Arafah – de beste dua.", "De beste dua is de dua van de Dag van Arafah, en de beste woorden zijn deze."),
        "dua_takbeer_tashreeq" to DuaText("Takbeer-e-Tashreeq", "Allah is de Grootste, Allah is de Grootste. Er is geen god dan Allah. Allah is de Grootste, Allah is de Grootste en alle lof is voor Allah.", "Na elk verplicht gebed van Fajr van 9 Dhul-Hijjah tot Asr van 13 Dhul-Hijjah.", "Overgeleverd door Ali en Ibn Mas'ud (RA) - wajib volgens de Hanafi's."),
        "dua_zamzam" to DuaText("Zamzam drinken", "O Allah, ik vraag U om nuttige kennis, overvloedige voorziening en genezing van elke ziekte.", "Als je Zamzam drinkt, doe dan dua voor wat je ook van plan bent.", "Zamzam is waarvoor het dronken wordt (Ibn Majah 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("Reflecteren op de schepping", "Onze Heer, U hebt dit alles niet voor niets geschapen. Glorie zij U, bescherm ons dus tegen de bestraffing van het Vuur.", "De dua van degenen die nadenken over de schepping van de hemel en de aarde.", "De dua van mensen met begrip (ulul-albab)."),
        "dua_q_sami_na_munadiyan" to DuaText("Wij hoorden de oproeper tot geloof", "Onze Heer, we hoorden een oproeper tot geloof roepen en zeggen: 'Geloof in uw Heer', en we geloofden. Onze Heer, vergeef ons onze zonden, verwijder onze wandaden van ons en laat ons sterven met de rechtvaardigen.", "Een dua voor geloof en sterven onder de rechtvaardigen.", "Een dua voor vergeving en een goed einde."),
        "dua_q_atina_ma_waadtana" to DuaText("Geef ons wat u beloofd heeft", "Onze Heer, schenk ons ​​wat U ons door Uw Boodschappers hebt beloofd en maak ons ​​niet te schande op de Dag der Opstanding. U breekt inderdaad Uw belofte niet.", "Toevlucht voor schande op de Dag der Opstanding.", "Eer zoeken in het Hiernamaals."),
        "dua_q_israfana" to DuaText("Vergeef onze excessen", "Onze Heer, vergeef ons onze zonden en onze excessen in onze zaken, maak onze voeten stevig en help ons tegen de ongelovige mensen.", "De dua van de metgezellen van eerdere profeten.", "Een dua voor standvastigheid en vergeving."),
        "dua_q_jamiun_nas" to DuaText("Jullie zullen de mensheid verzamelen", "Onze Heer, U zult de mensheid zeker verzamelen op een Dag waarover geen twijfel bestaat. Allah breekt Zijn belofte niet.", "Bevestiging van zekerheid op de Dag der Opstanding.", "De du van degenen die stevig geworteld zijn in kennis."),
        "dua_q_maash_shahidin" to DuaText("Schrijf ons onder de getuigen", "Onze Heer, wij hebben geloofd, schrijf ons daarom onder de getuigen.", "De du van degenen die de waarheid erkenden en geloofden.", "Een dua voor de aanvaarding van iemands geloof."),
        "dua_q_la_tajalna_zalimin" to DuaText("Niet met de overtreders", "Onze Heer, plaats ons niet bij de onrechtvaardige mensen.", "De dua van de mensen van al-A'raf.", "Toevlucht voor het lot van de overtreders."),
        "dua_q_tawaffana_muslimin" to DuaText("Geduld en dood als moslims", "Onze Heer, giet geduld over ons uit en zorg ervoor dat wij als moslims sterven.", "De dua van de magiërs van Farao toen zij geloofden.", "Geduld in beproevingen en een einde aan geloof."),
        "dua_q_la_tajalna_fitnah" to DuaText("Geen proces voor de onderdrukkers", "Op Allah vertrouwen wij. Onze Heer, maak ons ​​geen beproeving voor de onrechtvaardige mensen, en red ons door Uw genade van de ongelovige mensen.", "De dua van het volk van Musa (AS).", "Een dua voor redding van onderdrukking en onderdrukkers."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Dua van Nuh (AS) voor vergeving", "Mijn Heer, ik zoek mijn toevlucht bij U om U niet te vragen om iets waarvan ik geen kennis heb. En tenzij U mij vergeeft en medelijden met mij heeft, zal ik tot de verliezers behoren.", "Het dua van berouw van Profeet Noeh (AS).", "Een les in vragen met de juiste manieren."),
        "dua_q_mudkhala_sidq" to DuaText("Ingang en uitgang van de waarheid", "Mijn Heer, zorg ervoor dat ik met de waarheid binnenkom en met de waarheid naar buiten ga, en schenk mij van Uzelf een ondersteunende autoriteit.", "Voordat u een nieuwe taak, huis of plaats invoert.", "De dua onderwezen aan de Profeet ﷺ ten tijde van de Hijrah."),
        "dua_q_la_tadharni_fardan" to DuaText("Dua van Zakariya (AS) - Laat me niet alleen", "Mijn Heer, laat mij niet met rust, en U bent de beste erfgenaam.", "Voor wie kinderen zoekt.", "Via deze dua schonk Allah Yahya (AS)."),
        "dua_q_munzalan_mubarakan" to DuaText("Een gezegende landingsplaats", "Mijn Heer, laat mij landen op een gezegende landingsplaats, en U bent de beste van degenen die aan land komen.", "Bij het verhuizen naar een nieuw huis of ergens stoppen – de dua van Nuh (AS).", "Een dua voor zegening op een nieuwe plek."),
        "dua_q_amanna_faghfir" to DuaText("Wij geloven, dus vergeef ons", "Onze Heer, wij hebben geloofd, dus vergeef ons en heb medelijden met ons, en U bent de beste van de barmhartigen.", "De dua van Allah's rechtvaardige dienaren.", "Een alomvattende dua voor vergeving en barmhartigheid."),
        "dua_q_isrif_jahannam" to DuaText("Voorkom de straf van de hel", "Onze Heer, wend de bestraffing van de hel van ons af; inderdaad, de straf ervan is altijd aanhoudend. Het is inderdaad een slechte nederzetting en verblijfplaats.", "De dua van de dienaren van de Meest Barmhartige ('Ibad ar-Rahman).", "Een Quranische dua voor toevlucht uit de hel."),
        "dua_q_hab_li_hukman" to DuaText("Dua van Ibrahim (AS) – Wijsheid en Jannah", "Mijn Heer, schenk mij wijsheid en sluit mij aan bij de rechtvaardigen, geef mij een eervolle vermelding onder latere generaties, en maak mij tot de erfgenamen van de Tuin van Gelukzaligheid.", "Vragen om wijsheid, het gezelschap van de rechtvaardigen en het Paradijs.", "Een uitgebreide dua van Ibrahim (AS)."),
        "dua_q_lut_najjini_ahli" to DuaText("Dua van Lut (AS) — Red mijn familie", "Mijn Heer, red mij en mijn familie van (de gevolgen van) wat ze doen.", "Je gezin beschermen tegen een omgeving van kwaad.", "Bescherming van het gezin tegen het kwaad."),
        "dua_q_sulaiman_awzini" to DuaText("Dua van Sulaiman (AS) voor dankbaarheid", "Mijn Heer, stel mij in staat dankbaar te zijn voor Uw gunst die U mij en mijn ouders hebt geschonken, en rechtvaardige daden te doen die U behagen, en mij door Uw genade toe te laten onder Uw rechtvaardige dienaren.", "Voor het vermogen om dankbaar te zijn voor zegeningen.", "De dua van dankbaarheid van Sulayman (AS)."),
        "dua_q_musa_zalamtu" to DuaText("Dua van Musa (AS) - Ik heb mezelf onrecht aangedaan", "Mijn Heer, ik heb mezelf onrecht aangedaan, dus vergeef mij.", "Onmiddellijk berouw na een fout.", "Allah vergaf Musa (AS)."),
        "dua_q_musa_najjini" to DuaText("Dua van Musa (AS) — Red mij van onderdrukkers", "Mijn Heer, red mij van de onrechtvaardige mensen.", "Als je bang bent voor onderdrukkers.", "De dua van Musa (AS) bij het verlaten van Egypte."),
        "dua_q_lut_unsurni" to DuaText("Dua van Lut (AS) – Hulp tegen corrupties", "Mijn Heer, help mij tegen het verderfelijke volk.", "Voor hulp tegen degenen die corruptie verspreiden.", "De du van degenen die standvastig staan ​​in de waarheid."),
        "dua_q_hab_li_salihin" to DuaText("Dua van Ibrahim (AS) voor een rechtvaardig kind", "Mijn Heer, schenk mij (een kind) uit de rechtvaardigen.", "Vraag om rechtvaardige kinderen.", "Via deze dua werd Isma'il (AS) verleend."),
        "dua_q_wasita_kulla_shay" to DuaText("Dua van de engelen die de troon dragen", "Onze Heer, U omvat alle dingen in genade en kennis, dus vergeef degenen die berouw tonen en Uw weg volgen, en bescherm hen tegen de bestraffing van de hel.", "De engelen die de troon dragen, maken deze dua voor de gelovigen.", "Gereciteerd met de bedoeling opgenomen te worden in de dua van de engelen."),
        "dua_q_ikhwanina" to DuaText("Voor onze broeders die ons zijn voorgegaan", "Onze Heer, vergeef ons en onze broeders die ons in het geloof zijn voorgegaan, en koester geen wrok in onze harten jegens degenen die geloven. Onze Heer, U bent inderdaad vriendelijk en barmhartig.", "Een dua voor de gelovigen die eerder kwamen en voor een rein hart.", "Een dua voor de nobele metgezellen (RA) en de vroegere gelovigen."),
        "dua_q_alayka_tawakkalna" to DuaText("Op u vertrouwen wij (Ibrahim AS)", "Onze Heer, op U vertrouwen wij, tot U keren wij ons en tot U is de terugkeer. Onze Heer, maak ons ​​geen beproeving voor de ongelovigen en vergeef ons. Onze Heer, U bent inderdaad de Almachtige, de Wijze.", "De dua van Ibrahim (AS) en zijn metgezellen.", "Een dua van vertrouwen op Allah en je tot Hem wenden."),
        "dua_q_atmim_nurana" to DuaText("Perfectioneer ons licht", "Onze Heer, vervolmaak ons ​​licht voor ons en vergeef ons. U heeft inderdaad macht over alle dingen.", "De dua van de gelovigen op de Dag der Opstanding.", "Ik vraag om licht op de Sirat."),
        "dua_q_asiya_baytan" to DuaText("Dua van Asiya – Een huis in Jannah", "Mijn Heer, bouw voor mij vlakbij U een huis in het Paradijs, red mij van Farao en zijn daden, en red mij van de onrechtvaardige mensen.", "De dua van Asiya, de vrouw van Farao.", "Allah heeft haar tot een voorbeeld gemaakt voor de gelovigen."),
        "dua_adhan_response" to DuaText("Reageren op de Adhan", "Er is geen macht en geen macht behalve bij Allah.", "Herhaal wat de muezzin zegt; bij 'Hayya 'alas-salah' en 'Hayya 'alal-falah' zeg dit.", "Iedereen die vanuit het hart reageert, zal het Paradijs betreden."),
        "dua_adhan_shahadah" to DuaText("Na de Shahada van de Muazzin", "En ook ik getuig dat niemand het recht heeft om aanbeden te worden behalve Allah, alleen, zonder partner, en dat Mohammed (ﷺ) Zijn dienaar en Boodschapper is. Ik ben tevreden met Allah als Heer, met Mohammed ﷺ als Boodschapper en met de Islam als religie.", "Bij het horen van de geloofsgetuigenis van de muezzin.", "Zijn zonden zijn vergeven."),
        "dua_istiftah_baid" to DuaText("Openingsdua: Neem afstand van zonden", "O Allah, verwijder mij van mijn zonden zoals U het oosten van het westen hebt gescheiden. O Allah, reinig mij van zonden zoals een wit kledingstuk wordt gereinigd van vuil. O Allah, was mijn zonden weg met water, sneeuw en hagel.", "Na de openingstakbir (kan ook gezegd worden in plaats van de Sana).", "De Profeet ﷺ reciteerde dit tussen de takbir en de recitatie."),
        "dua_hamdan_kathiran" to DuaText("Overvloedige lof na Ruku", "Onze Heer, aan U behoort lof – overvloedige, zuivere en gezegende lof.", "Na het opstaan ​​uit ruku, samen met 'Rabbana lakal-hamd'.", "Meer dan dertig engelen renden om de eerste te zijn die het zou opnemen."),
    )
}
